effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode
vec4 u_xlat0;
vec4 u_xlat1;
bvec2 u_xlatb1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
bool u_xlatb4;
vec4 u_xlat5;
float u_xlat7;
int u_xlati7;
bool u_xlatb7;
vec2 u_xlat10;
vec2 u_xlat12;
float u_xlat13;
int u_xlati13;
bvec2 u_xlatb13;
int u_xlati19;
bool u_xlatb22;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat0.xy = u_xlat0.xy * vec2(_viewport_ratio.x, _viewport_ratio.y);
    u_xlat12.x = _cur_shake.w * 6.28318548;
    u_xlat1.x = sin(u_xlat12.x);
    u_xlat2.x = cos(u_xlat12.x);
    u_xlat3.x = sin((-u_xlat12.x));
    u_xlat3.y = u_xlat2.x;
    u_xlat3.z = u_xlat1.x;
    u_xlat1.x = dot(u_xlat0.xy, u_xlat3.yz);
    u_xlat1.y = dot(u_xlat0.xy, u_xlat3.xy);
    u_xlat12.x = _zoom + _cur_shake.z;
    u_xlat12.xy = u_xlat12.xx * u_xlat1.xy;
    u_xlat12.xy = u_xlat12.xy / vec2(_viewport_ratio.x, _viewport_ratio.y);
    u_xlat12.xy = u_xlat12.xy + _cur_shake.xy;
    u_xlat12.xy = u_xlat12.xy + vec2(0.5, 0.5);
    u_xlatb1.xy = lessThan(u_xlat12.xyxx, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb13.xy = lessThan(vec4(1.0, 1.0, 1.0, 1.0), u_xlat12.xyxy).xy;
    u_xlatb1.x = u_xlatb13.x || u_xlatb1.x;
    u_xlatb1.x = u_xlatb1.y || u_xlatb1.x;
    u_xlatb1.x = u_xlatb13.y || u_xlatb1.x;
    u_xlat1.x = (u_xlatb1.x) ? 0.0 : 1.0;
    u_xlat1.x = (int(_texture_wrap_mode) != 0) ? 1.0 : u_xlat1.x;
    u_xlatb7 = int(_texture_wrap_mode)==2;
    if(u_xlatb7){
        u_xlat2 = texture(SourceTexMirror, u_xlat12.xy);
    } else {
        u_xlat2 = texture(inputImg, u_xlat12.xy);
    }
    u_xlatb7 = 0<int(_enable_motion_blur);
    if(u_xlatb7){
        u_xlat7 = _prev_shake.w * 6.28318548;
        u_xlat3.x = sin(u_xlat7);
        u_xlat4.x = cos(u_xlat7);
        u_xlat5.x = sin((-u_xlat7));
        u_xlat5.y = u_xlat4.x;
        u_xlat5.z = u_xlat3.x;
        u_xlat3.x = dot(u_xlat0.xy, u_xlat5.yz);
        u_xlat3.y = dot(u_xlat0.xy, u_xlat5.xy);
        u_xlat0.x = _zoom + _prev_shake.z;
        u_xlat0.xy = u_xlat0.xx * u_xlat3.xy;
        u_xlat0.xy = u_xlat0.xy / vec2(_viewport_ratio.x, _viewport_ratio.y);
        u_xlat0.xy = u_xlat0.xy + _prev_shake.xy;
        u_xlat0.xy = u_xlat0.xy + vec2(0.5, 0.5);
        u_xlat0.xy = (-u_xlat0.xy) + u_xlat12.xy;
        u_xlati7 = int(_samples) + int(0xFFFFFFFFu);
        u_xlat7 = float(u_xlati7);
        u_xlat3 = u_xlat2;
        u_xlati13 = int(_texture_wrap_mode);
        for(int u_xlati_loop_1 = 0 ; u_xlati_loop_1<int(_samples) ; u_xlati_loop_1++)
        {
            u_xlat4.x = float(u_xlati_loop_1);
            u_xlat4.x = u_xlat4.x / u_xlat7;
            u_xlat10.xy = (-u_xlat0.xy) * u_xlat4.xx;
            u_xlat10.xy = (-u_xlat10.xy) * vec2(vec2(_length, _length)) + u_xlat12.xy;
            u_xlatb22 = u_xlati13==2;
            if(u_xlatb22){
                u_xlat5 = texture(SourceTexMirror, u_xlat10.xy);
            } else {
                u_xlat5 = texture(inputImg, u_xlat10.xy);
            }
            u_xlat4.z = u_xlat4.x * 3.0 + -1.5;
            u_xlat4.y = -abs(u_xlat4.z) + 1.0;
            u_xlat4.x = (-u_xlat4.z);
            u_xlat4.xyz = u_xlat4.xyz;
            u_xlat4.xyz = clamp(u_xlat4.xyz, 0.0, 1.0);
            u_xlat4.xyz = u_xlat4.xyz * u_xlat5.xyz;
            u_xlat4.xyz = u_xlat4.xyz * vec3(3.0, 3.0, 3.0) + (-u_xlat5.xyz);
            u_xlat5.xyz = vec3(_dispersion) * u_xlat4.xyz + u_xlat5.xyz;
            u_xlat3 = u_xlat3 + u_xlat5;
        }
        u_xlat0.x = float(int(_samples));
        u_xlat2 = u_xlat3 / u_xlat0.xxxx;
    }
    u_xlat0 = u_xlat1.xxxx * u_xlat2;
    u_xlatb1.xy = lessThan(ivec4(0, 0, 0, 0), ivec4(int(_enable_lumafade), int(_enable_exposure), int(_enable_lumafade), int(_enable_lumafade))).xy;
    u_xlat2 = vec4(_lumafade_strength) * (-u_xlat0) + u_xlat0;
    u_xlat13 = dot(u_xlat2, u_xlat2);
    u_xlat13 = sqrt(u_xlat13);
    u_xlat13 = log2(u_xlat13);
    u_xlat13 = u_xlat13 * _lumafade_inensity;
    u_xlat13 = exp2(u_xlat13);
    u_xlat13 = min(u_xlat13, 1.0);
    u_xlat2 = u_xlat0 * vec4(u_xlat13);
    u_xlat0 = (u_xlatb1.x) ? u_xlat2 : u_xlat0;
    u_xlat1.x = exp2(_exposure_strength);
    u_xlat1.xzw = u_xlat0.xyz * u_xlat1.xxx;
    u_xlat0.xyz = (u_xlatb1.y) ? u_xlat1.xzw : u_xlat0.xyz;
    if(int(_use_inner_mask) != 0) {
        u_xlat1 = texture(inputImg, acScreenNorm.xy);
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat0;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat1 = u_xlat1 * u_xlat5;
        u_xlat1 = u_xlat3 * u_xlat4 + u_xlat1;
        u_xlat2.x = u_xlat4.x * u_xlat1.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat1.w;
        fragColor.xyz = u_xlat1.xyz;
    } else {
        fragColor = u_xlat0;
    }
    return;
}
